<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { ElMessage } from 'element-plus/es/components/message/index.mjs';
import { staffApi as api, allPages } from '../../features/live/api';
import type { Category, KnowledgeDocument, KnowledgeVersion } from '../../features/live/knowledgeTypes';
import PreviewSelect from '../../features/preview/components/PreviewSelect.vue';
import PreviewDatePicker from '../../features/preview/components/PreviewDatePicker.vue';
import TableFooter from '../../features/preview/components/TableFooter.vue';
import Icon from '../../features/workbench/components/WorkbenchIcon.vue';
import { dateOf } from '../../features/workbench/types';
const emit=defineEmits<{updated:[]}>();
const categories=ref<Category[]>([]),documents=ref<KnowledgeDocument[]>([]),loading=ref(true),error=ref('');
const view=ref('documents'),search=ref(''),category=ref(''),page=ref(1),editor=ref(false),busy=ref(false),tab=ref('content');
const editing=ref<KnowledgeDocument|null>(null),preview=ref<{ordinal:number;content:string}[]|null>(null),dragging=ref(false),fileName=ref('');
const form=reactive({title:'',category_id:0,content:'',purpose:'',separator:'\\n\\n',target_chars:500,overlap_chars:50,start:'',end:''});
const categoryOpen=ref(false),editingCategory=ref<Category|null>(null),categoryForm=reactive({name:'',description:''});
const categoryError=ref('');let timer:ReturnType<typeof setInterval>|undefined,disposed=false,refreshing=false;
const filtered=computed(()=>documents.value.filter(d=>(!category.value||d.category_id===Number(category.value))&&`${d.title} ${d.published?.purpose || ''}`.includes(search.value.trim())));
const rows=computed(()=>filtered.value.slice((page.value-1)*8,page.value*8));
const pending=computed(()=>documents.value.some(d=>d.operation&&['PENDING','RUNNING'].includes(d.operation.status)));
watch([search,category],()=>page.value=1);
watch(()=>[form.content,form.separator,form.target_chars,form.overlap_chars],()=>preview.value=null,{flush:'sync'});
async function load(){if(refreshing)return;refreshing=true;
 try{const [cats,docs]=await Promise.all([api<{items:Category[]}>('/api/admin/knowledge-categories'),allPages<KnowledgeDocument>(api,'/api/admin/documents')]);
  if(disposed)return;categories.value=cats.items;documents.value=docs;error.value='';
 }catch(e){if(!disposed)error.value=(e as Error).message;}finally{loading.value=false;refreshing=false;}}
function categoryName(id:number){return categories.value.find(c=>c.id===id)?.name||'未分类';}
function localDate(value:string|null){if(!value)return '';const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
async function openDoc(row?:KnowledgeDocument){if(busy.value)return;error.value='';preview.value=null;tab.value='content';fileName.value='';
 try{const doc=row?await api<KnowledgeDocument>(`/api/admin/documents/${row.id}`):null;editing.value=doc;
  const v=doc?.candidate||doc?.published;const meta=doc?.candidate_metadata;
  Object.assign(form,{title:meta?.title||doc?.title||'',category_id:meta?.category_id||doc?.category_id||categories.value[0]?.id||0,
   content:v?.content||'',purpose:v?.purpose||'',separator:(v?.settings.separator||'\n\n').replaceAll('\n','\\n'),target_chars:v?.settings.target_chars||500,overlap_chars:v?.settings.overlap_chars??50,start:localDate(v?.effective_from||null),end:localDate(v?.effective_until||null)});
  editor.value=true;
 }catch(e){error.value=(e as Error).message;}}
function settings(){return {separator:form.separator.replaceAll('\\n','\n'),target_chars:Number(form.target_chars),overlap_chars:Number(form.overlap_chars)};}
async function parse(){busy.value=true;error.value='';try{const result=await api<{chunks:{ordinal:number;content:string}[]}>('/api/admin/knowledge/previews',{content:form.content,settings:settings()});preview.value=result.chunks;tab.value='preview';}
 catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function upload(file?:File){if(!file||busy.value)return;busy.value=true;error.value='';
 try{const data=new FormData();data.append('file',file);const result=await api<{title:string;content:string}>('/api/admin/knowledge/upload-text',data);form.content=result.content;if(!form.title)form.title=result.title;fileName.value=file.name;tab.value='content';}
 catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function fileSelected(e:Event){const input=e.target as HTMLInputElement;void upload(input.files?.[0]);input.value='';}
function drop(e:DragEvent){dragging.value=false;if((e.dataTransfer?.files.length||0)>1){error.value='一次请选择一个知识文件。';return;}void upload(e.dataTransfer?.files[0]);}
async function publish(){if(busy.value)return;busy.value=true;error.value='';
 try{await api('/api/admin/documents/publish',{document_id:editing.value?.id||null,expected_revision:editing.value?.revision||0,
   title:form.title,category_id:form.category_id,content:form.content,settings:settings(),purpose:editing.value?form.purpose:null,
   effective_from:form.start?new Date(form.start).toISOString():null,effective_until:form.end?new Date(form.end).toISOString():null});
  editor.value=false;await load();ElMessage.success('已提交发布，准备完成后自动生效');emit('updated');
 }catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function toggle(row:KnowledgeDocument){if(busy.value)return;busy.value=true;error.value='';try{await api(`/api/admin/documents/${row.id}`,{expected_revision:row.revision,enabled:!row.enabled},'PATCH');await load();emit('updated');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function restore(row:KnowledgeDocument){if(busy.value)return;busy.value=true;error.value='';try{await api(`/api/admin/documents/${row.id}/restore-previous`,{expected_revision:row.revision});await load();ElMessage.success('正在准备上一版内容，将保留该版原有效时间');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function openCategory(row?:Category){editingCategory.value=row||null;Object.assign(categoryForm,{name:row?.name||'',description:row?.description||''});categoryError.value='';categoryOpen.value=true;}
async function saveCategory(){if(busy.value)return;busy.value=true;categoryError.value='';try{await api(editingCategory.value?`/api/admin/knowledge-categories/${editingCategory.value.id}`:'/api/admin/knowledge-categories',
 {...categoryForm,...(editingCategory.value?{expected_revision:editingCategory.value.revision}:{})},editingCategory.value?'PATCH':'POST');categoryOpen.value=false;await load();ElMessage.success('知识库已保存');}catch(e){categoryError.value=(e as Error).message;}finally{busy.value=false;}}
async function removeCategory(row:Category){if(busy.value)return;busy.value=true;error.value='';try{await api(`/api/admin/knowledge-categories/${row.id}?expected_revision=${row.revision}`,undefined,'DELETE');await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function processing(row:KnowledgeDocument){return !!row.operation&&['PENDING','RUNNING'].includes(row.operation.status);}
onMounted(async()=>{await load();timer=setInterval(()=>{if(pending.value&&!busy.value)void load();},2000);});
onUnmounted(()=>{disposed=true;clearInterval(timer);});
</script>
<template><div class="pv-page live-page" :class="{'pv-editor-page':editor}"><div class="live-page-heading"><div><h1>{{editor?(editing?'编辑客服知识':'新增客服知识'):view==='categories'?'知识库':'客服知识'}}</h1><p>{{editor?'直接发布后自动处理；未发布的编辑不会保留。':'发布后的有效知识参与本店检索，失败或过期内容不参与回答。'}}</p></div><button v-if="editor" class="wb-btn" :disabled="busy" @click="editor=false;error=''">返回列表</button></div>
<p v-if="loading" class="live-muted">正在读取知识…</p><p v-if="error" class="live-error" role="alert">{{error}}</p>
<template v-if="!editor"><div class="live-subtabs"><button :class="{active:view==='documents'}" @click="view='documents'">客服知识</button><button :class="{active:view==='categories'}" @click="view='categories'">知识库</button></div>
<section v-if="view==='categories'" class="pv-card pv-categories-panel"><div class="pv-filters"><span class="pv-panel-meta">按业务用途整理本店知识</span><div class="pv-filter-end"><button class="wb-btn primary" @click="openCategory()"><Icon name="Plus"/>新建知识库</button></div></div><div class="pv-category-grid"><article v-for="c in categories" :key="c.id" class="pv-card pv-category-card"><span class="pv-category-symbol"><Icon name="Reading"/></span><h3>{{c.name}}</h3><p>{{c.description||'暂无用途说明'}}</p><div class="pv-category-bottom"><span>{{c.document_count}} 篇知识</span><button class="wb-text-button" @click="category=String(c.id);view='documents'">查看知识 →</button></div><div class="live-category-actions"><button class="wb-text-button" @click="openCategory(c)">编辑</button><button class="wb-text-button" :disabled="!!c.document_count||busy" @click="removeCategory(c)">删除空知识库</button></div></article></div><div v-if="!categories.length" class="pv-empty"><Icon name="Reading"/><strong>先创建一个知识库</strong><span>按用途分类后即可发布客服知识。</span></div></section>
<section v-else class="pv-card"><div class="pv-filters"><div class="pv-search"><Icon name="Search"/><input v-model="search" aria-label="搜索知识" placeholder="搜索知识标题或用途"/></div><PreviewSelect v-model="category" aria-label="知识库筛选"><option value="">全部知识库</option><option v-for="c in categories" :key="c.id" :value="String(c.id)">{{c.name}}</option></PreviewSelect><div class="pv-filter-end"><button class="wb-btn primary" :disabled="!categories.length||busy" @click="openDoc()"><Icon name="Plus"/>新增知识</button></div></div>
<div class="pv-table-scroll"><table class="pv-table"><thead><tr><th>知识标题 / 用途</th><th>所属知识库</th><th>状态 / 有效期</th><th>切片数</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="d in rows" :key="d.id"><td class="pv-wide-cell"><strong>{{d.title}}</strong><small>{{d.published?.purpose||'发布成功后自动生成用途'}}</small><small v-if="processing(d)" class="pv-positive">正在准备新版本…</small><small v-if="d.operation?.status==='FAILED'" class="live-inline-error">{{d.operation.error}}</small></td><td>{{categoryName(d.category_id)}}</td><td><span class="pv-tag" :class="d.state==='已发布'?'green':''">{{d.state}}</span><small>{{d.published?.effective_until?`至 ${dateOf(d.published.effective_until)}`:d.published?.effective_from?`${dateOf(d.published.effective_from)} 起`:'长期有效'}}</small></td><td>{{d.published?.chunk_count||0}}</td><td>{{dateOf(d.updated_at)}}</td><td><div class="pv-row-actions"><button :disabled="processing(d)||busy" @click="openDoc(d)">查看 / 编辑</button><button :disabled="busy" @click="toggle(d)">{{d.enabled?'停用':'启用'}}</button><button :disabled="!d.published||processing(d)||busy" @click="restore(d)">恢复上一版</button></div></td></tr></tbody></table></div><div v-if="!filtered.length" class="pv-empty"><Icon name="Reading"/><strong>没有符合条件的知识</strong><span>{{categories.length?'可以调整筛选或新增知识':'先在知识库页签创建分类'}}</span></div><TableFooter v-model:page="page" :total="filtered.length"/></section></template>
<template v-else><div class="pv-editor-grid"><section class="pv-card pv-editor-settings"><h3>知识信息</h3><div class="pv-form"><label>所属知识库<PreviewSelect v-model="form.category_id" aria-label="所属知识库" :disabled="busy"><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></PreviewSelect></label><label>标题<input v-model="form.title" aria-label="知识标题" :disabled="busy" maxlength="255"/></label><label v-if="editing">用途说明<textarea v-model="form.purpose" aria-label="用途说明" rows="3" maxlength="1000" :disabled="busy"/><small>新知识发布时自动生成，已有用途可修订。</small></label><div class="pv-form-divider"></div><h3>分段设置</h3><label>分隔符<input v-model="form.separator" aria-label="分隔符" :disabled="busy"/><small>使用 \n 表示换行</small></label><div class="pv-form-grid"><label>分段长度<input v-model.number="form.target_chars" aria-label="分段长度" type="number" min="100" max="4000" :disabled="busy"/></label><label>重叠长度<input v-model.number="form.overlap_chars" aria-label="重叠长度" type="number" min="0" :disabled="busy"/></label></div><button class="wb-btn" :disabled="busy" @click="parse">预览分段</button><small>修改正文或设置后需重新预览。</small><div class="pv-form-divider"></div><h3>有效时间</h3><label>生效时间<PreviewDatePicker v-model="form.start" type="datetime" aria-label="知识生效时间" :disabled="busy"/></label><label>失效时间<PreviewDatePicker v-model="form.end" type="datetime" aria-label="知识失效时间" :disabled="busy"/></label><details class="live-muted"><summary>有效期填写说明</summary>不填写表示长期有效。未来生效的版本在到期前不参与回答；已到期的最新版本不会自动恢复更早内容。</details></div></section>
<section class="pv-card live-knowledge-main"><div class="pv-panel-heading"><div class="live-subtabs"><button :class="{active:tab==='content'}" @click="tab='content'">知识正文</button><button :class="{active:tab==='preview'}" @click="tab='preview'">分段预览 {{preview?.length||''}}</button></div><button class="wb-btn primary" :disabled="busy||!form.content.trim()||!form.title.trim()" @click="publish">{{busy?'正在处理…':'发布生效'}}</button></div>
<div v-if="tab==='content'" class="live-knowledge-body"><label class="pv-upload-zone" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave="dragging=false" @drop.prevent="drop"><Icon name="UploadFilled"/><strong>{{fileName||'点击或拖入一个纯文本文件'}}</strong><span>UTF-8 编码，支持 MD、TXT 等，不超过 2 MB</span><input type="file" accept=".md,.markdown,.txt,.csv,.tsv,.json,.yaml,.yml,.xml,.log" :disabled="busy" hidden @change="fileSelected"/></label><textarea v-model="form.content" aria-label="知识正文" :disabled="busy" placeholder="也可以直接在这里填写客服知识…"/></div><div v-else class="live-chunk-preview"><p v-if="!preview" class="live-muted">点击左侧“预览分段”，查看本次内容；预览不会发布知识。</p><article v-for="chunk in preview||[]" :key="chunk.ordinal"><span class="pv-tag">切片 {{chunk.ordinal}}</span><p>{{chunk.content}}</p></article></div></section></div></template>
<el-dialog v-model="categoryOpen" :title="editingCategory?'编辑知识库':'新建知识库'" width="min(480px, 94vw)" class="wb-dialog" align-center><form class="pv-form" @submit.prevent="saveCategory"><label>名称<input v-model="categoryForm.name" aria-label="知识库名称" required maxlength="100"/></label><label>用途说明<textarea v-model="categoryForm.description" aria-label="知识库用途说明" rows="4" maxlength="2000"/></label><p v-if="categoryError" class="live-error" role="alert">{{categoryError}}</p><div class="live-form-actions"><button type="button" class="wb-btn" :disabled="busy" @click="categoryOpen=false">取消</button><button class="wb-btn primary" :disabled="busy">保存</button></div></form></el-dialog>
</div></template>
